 precision tailored seams, and signature MatchA earth tones.`, price, originalPrice, tag, image: primaryVariant.image, category: mainCat, subCategory: nameSub, season: nameSeason, color: primaryVariant.color, colorHex: primaryVariant.colorHex, fit, sizes: mainCat === 'Accessories' ? ['OS'] : ['S', 'M', 'L', 'XL', 'XXL'], variants: variants, inStock: idx % 11 !== 0, rating: Number((4.6 + (idx % 5) * 0.1).toFixed(1)), reviewsCount: 24 + (idx * 9) % 190, isFeatured: idx % 4 === 0, createdAt: '2026-02-' + String((idx % 26) + 1).padStart(2, '0') }); idx++; } console.log('Total Master Products generated:', masterProducts.length); // Write to backend const backendFile = path.resolve(__dirname, '../backend/data/products.js'); const backendContent = 'const products = ' + JSON.stringify(masterProducts, null, 2) + ';

